from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    sep=Counter(v for row in grid for v in row).most_common(2)[1][0]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # A separator line is almost entirely separator-colored.
    rows=[r for r in range(h) if grid[r].count(sep)>w//2]
    cols=[c for c in range(w) if sum(grid[r][c]==sep for r in range(h))>h//2]
    holes=[(r,c) for r in rows for c in range(w) if grid[r][c]!=sep]
    def framed(rs,cs):
        core=[[grid[r][c] for c in cs] for r in rs]
        left=[bg]+[sep]*len(core[0])+[bg]
        out=[left]
        for row in core:
            out.append([sep]+row+[sep])
        out.append(left)
        return out
    xs=sorted(set(c for r,c in holes)); ys=sorted(set(r for r,c in holes))
    if len(xs)==1:
        x=xs[0]; ce=next(c for c in cols if c>x)
        rs=[]
        for y in ys:
            a=max(r for r in rows if r<y)+1 if any(r<y for r in rows) else 0
            rs.extend(range(a,y))
        # keep the two disjoint tile rows, including their separating line
        if len(ys)==2:
            mid=next(r for r in rows if ys[0]<r<ys[1])
            rs=sorted(set(rs+[mid]))
        return framed(rs,list(range(x+1,ce)))
    if xs[0] in cols:
        # openings underneath tile strips
        tile_h=rows[0]
        if tile_h==3:
            return framed(list(range(ys[0]+1,ys[-1])),list(range(xs[0]+1,xs[-1])))
        if ys[-1]-ys[0] > 6:
            rs=[]
            for ye in ys:
                rs += list(range(max([r for r in rows if r<ye],default=-1)+1,ye))
            mid=next(r for r in rows if ys[0]<r<ys[-1])
            rs=sorted(set(rs+[mid]))
            return framed(rs,list(range(xs[0]+1,xs[-1])))
        ye=ys[0]
        rs=list(range(max([r for r in rows if r<ye],default=-1)+1,ye))
        return framed(rs,list(range(0,next(c for c in cols if c>xs[0]))))
    # openings around an interior rectangular strip
    rs=list(range(ys[0]+1,ys[-1]))
    cs=list(range(xs[0]+1,xs[-1]))
    return framed(rs,cs)

